// ======================================================================
// NODE: ORGANIZA + EDITA IMAGENS V11 (FULL + VIRAL ENGINE)
// ======================================================================
// BASE: V8 (Sua versão original robusta de 700 linhas)
// + UPGRADE V11: Novos Filtros Visuais de Alta Retenção (Dopamina/Deep)
// + UPGRADE V11: Lógica de seleção baseada em emoção para engajamento.
// ======================================================================

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// ==========================================
// ⚙️ CONFIGURAÇÃO - ALTERE AQUI
// ==========================================
const CONFIG = {
  pastaRaiz: '/tmp/youtubevideos',
  arquivoEstado: 'estado_capitulos.json',

  // 🔴 CONTROLES MANUAIS
  PAGINA_INICIAL_MANUAL: 0,
  PAGINA_FINAL_MANUAL: 0,

  // Ignora estado
  IGNORAR_ESTADO: false,

  // Força reprocessar
  FORCAR_REPROCESSAMENTO: false,

  // FFmpeg
  maxTentativasFFmpeg: 3,
  timeoutFFmpeg: 120000,

  // Compressão
  qualidadeAgente: 60,
  maxLarguraAgente: 1200,

  // Logs
  salvarLogs: true,
  pastaLogs: 'logs',

  // Efeitos
  evitarRepeticaoEfeitos: true,

  // 🚀 CONFIGURAÇÃO VIRAL (INTENSIDADE)
  SATURACAO_HYPE: 1.4,   // Cores vivas para reter atenção
  CONTRASTE_DRAMA: 1.25, // Contraste para imersão
  NITIDEZ_CRISPY: 1.0    // Nitidez para parecer HD no celular
};

// ==========================================
// 🎨 BIBLIOTECA DE EFEITOS VIRAIS (V11)
// ==========================================
// Estes filtros são "queimados" na imagem para garantir o visual no vídeo final.
const filters = [
  // 1. HYPE (Dopamina) - Para Comédia, Vitória, Tecnologia, Feliz
  // Aumenta saturação e nitidez. Cores saltam da tela.
  { 
    nome: "HYPE (Dopamina)", 
    tipo: "complex", 
    filter: `[0:v]split=2[bg][fg];[bg]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,boxblur=20:10[bg_blur];[fg]scale=1920:1080:force_original_aspect_ratio=decrease[fg_scaled];[bg_blur][fg_scaled]overlay=(W-w)/2:(H-h)/2,eq=saturation=${CONFIG.SATURACAO_HYPE}:contrast=1.1:brightness=0.05,unsharp=5:5:1.0:5:5:0.0`, 
    categoria: "dopamina" 
  },

  // 2. DEEP (Imersão) - Para Terror, Tensão, Medo, Mistério
  // Aumenta contraste, escurece, adiciona vinheta e leve ruído de filme.
  { 
    nome: "DEEP (Imersão)", 
    tipo: "complex", 
    filter: `[0:v]split=2[bg][fg];[bg]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,boxblur=20:10,eq=brightness=-0.7[bg_dark];[fg]scale=1920:1080:force_original_aspect_ratio=decrease[fg_scaled];[bg_dark][fg_scaled]overlay=(W-w)/2:(H-h)/2,eq=saturation=0.6:contrast=${CONFIG.CONTRASTE_DRAMA}:brightness=-0.05,vignette=PI/3,noise=alls=5:allf=t+u`, 
    categoria: "drama" 
  },

  // 3. IMPACT (Ação) - Para Luta, Raiva, Grito, Impacto
  // Nitidez extrema, alto contraste, leve desvio de cor (chroma).
  { 
    nome: "IMPACT (Ação)", 
    tipo: "complex", 
    filter: `[0:v]split=2[bg][fg];[bg]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,boxblur=20:10[bg_blur];[fg]scale=1920:1080:force_original_aspect_ratio=decrease[fg_scaled];[fg_scaled]split=2[orig][shadow];[shadow]drawbox=t=fill:c=black@0.6,scale=iw*1.02:ih*1.02[shadow_layer];[bg_blur][shadow_layer]overlay=(W-w)/2:(H-h)/2[bg_w_shadow];[bg_w_shadow][orig]overlay=(W-w)/2:(H-h)/2,eq=contrast=1.2:saturation=1.1,unsharp=7:7:1.5:7:7:0.0`, 
    categoria: "acao" 
  },

  // 4. NOSTALGIA (Emoção) - Para Flashback, Tristeza, Memória
  // Tom sépia, suavidade (boxblur leve), cores lavadas.
  { 
    nome: "NOSTALGIA (Sépia)", 
    tipo: "complex", 
    filter: `[0:v]split=2[bg][fg];[bg]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,boxblur=20:10,colorchannelmixer=.393:.769:.189:0:.349:.686:.168:0:.272:.534:.131[bg_sepia];[fg]scale=1920:1080:force_original_aspect_ratio=decrease[fg_scaled];[bg_sepia][fg_scaled]overlay=(W-w)/2:(H-h)/2,colorchannelmixer=.393:.769:.189:0:.349:.686:.168:0:.272:.534:.131,boxblur=2:1`, 
    categoria: "flashback" 
  },

  // 5. LOVE (Romance) - Para Romance, Amor, Timidez
  // Tom rosado, brilho (bloom simulado), suavidade.
  { 
    nome: "LOVE (Bloom)", 
    tipo: "complex", 
    filter: `[0:v]split=2[bg][fg];[bg]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,boxblur=40:20,colorbalance=rs=0.2:gs=0.1:bs=0.2[bg_pink];[fg]scale=1920:1080:force_original_aspect_ratio=decrease[fg_scaled];[bg_pink][fg_scaled]overlay=(W-w)/2:(H-h)/2,eq=saturation=1.2:contrast=1.05,colorbalance=rs=0.05:bs=0.05,unsharp=5:5:0.8`, 
    categoria: "romance" 
  },

  // 6. STANDARD POLISHED (Neutro) - Para cenas normais
  // Não deixa a imagem crua. Aplica tratamento profissional padrão.
  { 
    nome: "STANDARD (Polido)", 
    tipo: "complex", 
    filter: `[0:v]split=2[bg][fg];[bg]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,boxblur=20:10[bg_blur];[fg]scale=1920:1080:force_original_aspect_ratio=decrease[fg_scaled];[bg_blur][fg_scaled]overlay=(W-w)/2:(H-h)/2,eq=saturation=1.15:contrast=1.05,unsharp=3:3:0.5`, 
    categoria: "neutro" 
  },

  // 7. SAFE MODE (Censura) - Para imagens censuradas
  // Escurece e dessatura para não chamar atenção do algoritmo.
  { 
    nome: "CENSURA (Safe)", 
    tipo: "complex", 
    filter: `[0:v]split=2[bg][fg];[bg]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,boxblur=20:10[bg_blur];[fg]scale=1920:1080:force_original_aspect_ratio=decrease[fg_scaled];[bg_blur][fg_scaled]overlay=(W-w)/2:(H-h)/2,eq=brightness=-0.1:saturation=0.8,boxblur=2:1`, 
    categoria: "censura" 
  }
];

// Mantemos os movimentos apenas para constar no JSON, caso o vídeo use no futuro
const movements = [
  { name: "Standard Zoom", filter: "zoompan=z='min(zoom+0.001,1.2)':d=10000:x='iw/2-(iw/zoom/2)':y='ih/4':s=1920x1080" }
];

// ==========================================
// FUNÇÕES DE LOG
// ==========================================
function criarPastaLogs(pastaObra) {
  const pastaLogs = path.join(pastaObra, CONFIG.pastaLogs);
  if (!fs.existsSync(pastaLogs)) {
    fs.mkdirSync(pastaLogs, { recursive: true });
  }
  return pastaLogs;
}

function log(pastaObra, mensagem, tipo = 'INFO') {
  const timestamp = new Date().toISOString();
  const linha = `[${timestamp}] [${tipo}] ${mensagem}`;

  console.log(linha);

  if (CONFIG.salvarLogs && pastaObra) {
    try {
      const pastaLogs = criarPastaLogs(pastaObra);
      const dataHoje = new Date().toISOString().split('T')[0];
      const arquivoLog = path.join(pastaLogs, `organiza_${dataHoje}.log`);
      fs.appendFileSync(arquivoLog, linha + '\n', 'utf8');
    } catch (e) {}
  }
}

// ==========================================
// FUNÇÕES AUXILIARES
// ==========================================

function carregarEstado(pastaObra) {
  if (CONFIG.IGNORAR_ESTADO) {
    console.log('⚠️ IGNORAR_ESTADO=true - Não verificando estado');
    return null;
  }

  const caminhoEstado = path.join(pastaObra, CONFIG.arquivoEstado);

  if (fs.existsSync(caminhoEstado)) {
    try {
      const conteudo = fs.readFileSync(caminhoEstado, 'utf8');
      const estado = JSON.parse(conteudo);
      return estado;
    } catch (e) {
      console.log(`Erro ao carregar estado: ${e.message}`);
      return null;
    }
  }

  console.log(`📂 Arquivo de estado não existe: ${caminhoEstado}`);
  return null;
}

// Lista todas as imagens no disco
function listarImagensNoDisco(pastaObra) {
  const imagens = [];

  if (!fs.existsSync(pastaObra)) {
    return imagens;
  }

  const arquivos = fs.readdirSync(pastaObra);

  for (const arquivo of arquivos) {
    const match = arquivo.match(/^(\d+)\.jpg$/i);

    if (match) {
      const numero = parseInt(match[1]);
      const caminhoCompleto = path.join(pastaObra, arquivo);

      try {
        const stats = fs.statSync(caminhoCompleto);
        if (stats.size > 1024) { 
          imagens.push({
            numero: numero,
            arquivo: arquivo,
            caminho: caminhoCompleto,
            tamanho: stats.size
          });
        }
      } catch (e) {}
    }
  }

  imagens.sort((a, b) => a.numero - b.numero);
  return imagens;
}

// Verifica quais páginas estão pendentes
function identificarPaginasPendentes(imagens, estado) {
  const pendentes = [];
  const jaProcessadas = [];

  for (const img of imagens) {
    const paginaGlobal = img.numero;

    if (CONFIG.IGNORAR_ESTADO || CONFIG.FORCAR_REPROCESSAMENTO) {
      pendentes.push(img);
      continue;
    }

    const infoPagina = estado?.paginasProcessadas?.[paginaGlobal];

    if (infoPagina && infoPagina.status === 'ok') {
      jaProcessadas.push(paginaGlobal);
    } else {
      pendentes.push(img);
    }
  }

  return { pendentes, jaProcessadas };
}

function validarBinario(binary) {
  if (!binary) return false;
  const chave = Object.keys(binary)[0];
  if (!chave) return false;
  const dados = binary[chave];
  if (!dados) return false;
  if (!dados.data && !Buffer.isBuffer(dados)) return false;
  return true;
}

let ultimoEfeitoUsado = -1;

// 🔴 SELEÇÃO DE EFEITO VIRAL INTELIGENTE (V11)
function selecionarEfeito(nomeArquivo, index, efeitosRecomendados = {}, isCensored = false) {
  const paginaNum = parseInt(nomeArquivo.toString().replace(/\D/g, '')) || index;

  // Se estiver censurado, usa o modo SAFE imediatamente
  if (isCensored) {
      return {
        filter: filters[6].filter, // Filtro CENSURA
        filterName: filters[6].nome,
        filterCategoria: "censura",
        isSimple: false,
        movement: movements[0]
      };
  }

  // Tenta pegar a emoção recomendada pelo Agente
  let emocao = 'neutro';
  if (efeitosRecomendados[paginaNum]) {
    emocao = (efeitosRecomendados[paginaNum].emocao || 'neutro').toLowerCase();
  }

  // Mapeia Emoção -> Filtro Visual
  let filtroSelecionado;

  if (['comedia', 'vitoria', 'tecnologia', 'feliz', 'deboche', 'alegria'].includes(emocao)) {
      filtroSelecionado = filters[0]; // HYPE
  } else if (['tensao', 'medo', 'horror', 'suspense', 'misterio', 'susto'].includes(emocao)) {
      filtroSelecionado = filters[1]; // DEEP
  } else if (['acao', 'raiva', 'grito', 'luta', 'combate', 'odio'].includes(emocao)) {
      filtroSelecionado = filters[2]; // IMPACT
  } else if (['flashback', 'tristeza', 'memoria', 'saudade', 'triste'].includes(emocao)) {
      filtroSelecionado = filters[3]; // NOSTALGIA
  } else if (['romance', 'amor', 'timidez', 'paixao'].includes(emocao)) {
      filtroSelecionado = filters[4]; // LOVE
  } else {
      filtroSelecionado = filters[5]; // STANDARD (Neutro mas polido)
  }

  // Retorno compatível com V8
  return {
    filter: filtroSelecionado.filter,
    filterName: filtroSelecionado.nome,
    filterIndex: 0,
    filterCategoria: filtroSelecionado.categoria,
    isSimple: false, // Todos agora são complexos
    movement: movements[0] // Placeholder
  };
}

function aplicarEfeito(inputPath, outputPath, efeito, pastaObra) {
  const filterType = efeito.isSimple ? "-vf" : "-filter_complex";
  const cmd = `ffmpeg -y -i "${inputPath}" ${filterType} "${efeito.filter}" -q:v 2 "${outputPath}" 2>/dev/null`;

  for (let tentativa = 1; tentativa <= CONFIG.maxTentativasFFmpeg; tentativa++) {
    try {
      execSync(cmd, { timeout: CONFIG.timeoutFFmpeg });

      if (fs.existsSync(outputPath)) {
        const stats = fs.statSync(outputPath);
        if (stats.size > 1024) {
          return { sucesso: true, tentativas: tentativa };
        }
      }
    } catch (e) {
      if (tentativa === CONFIG.maxTentativasFFmpeg) {
        log(pastaObra, `FFmpeg falhou após ${tentativa} tentativas`, 'WARN');
      }
    }
    if (tentativa < CONFIG.maxTentativasFFmpeg) execSync('sleep 1');
  }

  try {
    fs.copyFileSync(inputPath, outputPath);
    return { sucesso: false, usouFallback: true };
  } catch (e) {
    return { sucesso: false, erro: e.message };
  }
}

function comprimirParaAgente(inputPath, pastaObra) {
  const tempPath = inputPath.replace('.jpg', '_agente_temp.jpg');
  try {
    const cmd = `ffmpeg -y -i "${inputPath}" -vf "scale='min(${CONFIG.maxLarguraAgente},iw)':-1" -q:v ${Math.floor((100 - CONFIG.qualidadeAgente) / 10 + 2)} "${tempPath}" 2>/dev/null`;
    execSync(cmd, { timeout: 30000 });

    if (fs.existsSync(tempPath)) {
      const buffer = fs.readFileSync(tempPath);
      fs.unlinkSync(tempPath);
      return buffer;
    }
  } catch (e) {}
  return fs.readFileSync(inputPath);
}

// ==========================================
// 🚀 LÓGICA PRINCIPAL (V11)
// ==========================================

const items = $input.all();
const primeiroItem = items[0]?.json || {};

// 🔴 RESGATE DE MEMÓRIA (FIX V6)
let itensOriginaisGerenciador = [];
try {
    itensOriginaisGerenciador = $('GERENCIADOR MASTER').all();
    console.log(`✅ Memória recuperada: ${itensOriginaisGerenciador.length} itens do Gerenciador`);
} catch(e) {
    console.log("⚠️ Aviso: Não foi possível ler memória do Gerenciador Master");
}

console.log('');
console.log('═══════════════════════════════════════════════════════════');
console.log('🚀 ORGANIZA + EDITA IMAGENS V11 (FULL + VIRAL ENGINE)');
console.log('═══════════════════════════════════════════════════════════');
console.log(`📅 ${new Date().toISOString()}`);
console.log('');
console.log('⚙️ CONFIGURAÇÕES:');
console.log(`   PAGINA_INICIAL_MANUAL: ${CONFIG.PAGINA_INICIAL_MANUAL}`);
console.log(`   PAGINA_FINAL_MANUAL: ${CONFIG.PAGINA_FINAL_MANUAL}`);
console.log(`   IGNORAR_ESTADO: ${CONFIG.IGNORAR_ESTADO}`);
console.log(`   FORCAR_REPROCESSAMENTO: ${CONFIG.FORCAR_REPROCESSAMENTO}`);
console.log('');

// ==========================================
// 1. DESCOBRE A PASTA DA OBRA
// ==========================================
let obra = primeiroItem.obra || primeiroItem._controle?.obra || "Obra_Desconhecida";
let capitulo = primeiroItem.capitulo || "cap1";
let pastaObra = primeiroItem.pastaObra || null;

try {
  const configNode = $('Configura Obra1').first().json;
  if (configNode) {
    const nomeCompleto = configNode.nome_obra || '';
    if (nomeCompleto.toLowerCase().startsWith('cap')) {
      const partes = nomeCompleto.split('-');
      if (partes.length > 1) {
        capitulo = partes[0];
        obra = partes.slice(1).join('-');
      } else {
        obra = nomeCompleto;
      }
    } else if (nomeCompleto) {
      obra = nomeCompleto;
      capitulo = configNode.capitulo || 'cap1';
    }
    console.log(`📍 De Configura Obra1: obra=${obra}, capitulo=${capitulo}`);
  }
} catch (e) {}

if (!pastaObra) {
  pastaObra = path.join(CONFIG.pastaRaiz, obra);
}

log(pastaObra, `📁 Obra: ${obra}`);
log(pastaObra, `📖 Capítulo: ${capitulo}`);
log(pastaObra, `📂 Pasta: ${pastaObra}`);

if (!fs.existsSync(pastaObra)) {
  fs.mkdirSync(pastaObra, { recursive: true });
  log(pastaObra, `📁 Pasta criada: ${pastaObra}`);
}

// ==========================================
// 2. DETECTA MODO DE OPERAÇÃO
// ==========================================
const temBinariosDoNode = items.some(item => validarBinario(item.binary));
const modoPularDownload = primeiroItem._pularDownload === true;

log(pastaObra, '');
log(pastaObra, '🔍 DETECTANDO MODO DE OPERAÇÃO...');
log(pastaObra, `   Items recebidos: ${items.length}`);
log(pastaObra, `   Tem binários válidos: ${temBinariosDoNode}`);
log(pastaObra, `   Flag _pularDownload: ${modoPularDownload}`);

// ==========================================
// MODO 1: PRIMEIRA EXECUÇÃO (DO DRIVE)
// ==========================================
if (temBinariosDoNode && !modoPularDownload) {
  log(pastaObra, '');
  log(pastaObra, '📥 MODO: PRIMEIRA EXECUÇÃO (salvando do Drive)');
  log(pastaObra, '═══════════════════════════════════════════════════════════');

  const estado = carregarEstado(pastaObra);
  const efeitosRecomendados = estado?.efeitosRecomendados || {};

  const processados = [];
  let imagensSalvas = 0;
  let imagensIgnoradas = 0;

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const json = item.json;

    // 🔴 RESGATE DE MEMÓRIA (LÓGICA V6)
    let paginaGlobal = json.paginaGlobal;
    if (!paginaGlobal && itensOriginaisGerenciador.length > i) {
        paginaGlobal = itensOriginaisGerenciador[i].json.paginaGlobal;
    }
    if (!paginaGlobal) {
        paginaGlobal = (i + 1);
        console.log(`⚠️ Alerta: Fallback sequencial item ${i} -> Pag ${paginaGlobal}`);
    }

    // 🔴 VERIFICA SE FOI CENSURADO (LÓGICA V7)
    const isCensored = json.needs_censoring === true;

    const paginaLocal = json.paginaLocal || (i + 1);
    const nomeOriginal = json.name || `img_${paginaGlobal}`;

    const caminhoOriginal = json.caminhoOriginal || path.join(pastaObra, `${paginaGlobal}.jpg`);
    const caminhoEditado = json.caminhoEditado || path.join(pastaObra, `${paginaGlobal}_editado.jpg`);

    if (!CONFIG.FORCAR_REPROCESSAMENTO && !CONFIG.IGNORAR_ESTADO) {
      const statusPagina = estado?.paginasProcessadas?.[paginaGlobal]?.status;
      if (statusPagina === 'ok') {
        log(pastaObra, `⏭️ Pág ${paginaGlobal}: já processada (pulando)`);
        imagensIgnoradas++;
        continue;
      }
    }

    if (CONFIG.PAGINA_INICIAL_MANUAL > 0 && paginaGlobal < CONFIG.PAGINA_INICIAL_MANUAL) {
      log(pastaObra, `⏭️ Pág ${paginaGlobal}: antes da página inicial manual (pulando)`);
      imagensIgnoradas++;
      continue;
    }
    if (CONFIG.PAGINA_FINAL_MANUAL > 0 && paginaGlobal > CONFIG.PAGINA_FINAL_MANUAL) {
      log(pastaObra, `⏭️ Pág ${paginaGlobal}: depois da página final manual (pulando)`);
      imagensIgnoradas++;
      continue;
    }

    log(pastaObra, `📄 Processando página ${paginaGlobal} (local: ${paginaLocal}) [Censurado: ${isCensored}]`);

    if (!validarBinario(item.binary)) {
      log(pastaObra, `⚠️ Pág ${paginaGlobal}: binário inválido`, 'WARN');
      continue;
    }

    let bufferOriginal;
    try {
      const binaryKey = Object.keys(item.binary)[0];
      bufferOriginal = await this.helpers.getBinaryDataBuffer(i, binaryKey);
      fs.writeFileSync(caminhoOriginal, bufferOriginal);
      log(pastaObra, `  💾 Original salvo: ${bufferOriginal.length} bytes → ${caminhoOriginal}`);
      imagensSalvas++;
    } catch (e) {
      log(pastaObra, `  ❌ Erro ao salvar: ${e.message}`, 'ERROR');
      continue;
    }

    // APLICA EFEITO VIRAL (COM TRAVA DE SEGURANÇA)
    const efeito = selecionarEfeito(nomeOriginal, paginaGlobal, efeitosRecomendados, isCensored);

    if (isCensored) {
        log(pastaObra, `  🔒 Censura Detectada: Aplicando tratamento SAFE.`);
    } else {
        log(pastaObra, `  🎨 Aplicando tratamento viral: ${efeito.filterName}`);
    }

    const resultadoEfeito = aplicarEfeito(caminhoOriginal, caminhoEditado, efeito, pastaObra);

    if (resultadoEfeito.sucesso) {
      log(pastaObra, `  ✨ Finalizada: ${efeito.filterName} (${resultadoEfeito.tentativas} tentativa(s))`);
    } else if (resultadoEfeito.usouFallback) {
      log(pastaObra, `  ⚠️ Fallback: copiou original`, 'WARN');
    }

    const bufferAgente = comprimirParaAgente(caminhoEditado, pastaObra);

    processados.push({
      paginaGlobal,
      paginaLocal,
      nomeOriginal,
      caminhoOriginal,
      caminhoEditado,
      efeito: efeito.filterName,
      efeitoCategoria: efeito.filterCategoria,
      bufferAgente,
      isCensored 
    });
  }

  log(pastaObra, '');
  log(pastaObra, `📊 Imagens salvas: ${imagensSalvas}`);
  log(pastaObra, `📊 Imagens ignoradas: ${imagensIgnoradas}`);

  if (processados.length === 0) {
    return [{ 
      json: { 
        status: 'TUDO_PROCESSADO', 
        obra, 
        capitulo,
        pastaObra,
        mensagem: 'Todas as páginas já foram processadas anteriormente'
      } 
    }];
  }

  processados.sort((a, b) => a.paginaGlobal - b.paginaGlobal);

  const binarios = {};
  const listaPaginas = [];
  const metadados = [];

  for (let i = 0; i < processados.length; i++) {
    const p = processados[i];
    const novaChave = i === 0 ? 'data' : `data${i}`;

    binarios[novaChave] = {
      data: p.bufferAgente.toString('base64'),
      mimeType: 'image/jpeg',
      fileName: `${p.paginaGlobal}.jpg`
    };

    listaPaginas.push(p.paginaGlobal);

    metadados.push({
      pagina_numero: p.paginaGlobal,
      paginaGlobal: p.paginaGlobal,
      paginaLocal: p.paginaLocal,
      nome_original: p.nomeOriginal,
      caminho_original: p.caminhoOriginal,
      caminho_editado: p.caminhoEditado,
