  }];
}

// ==========================================
// MODO 2: RE-EXECUÇÃO (DO DISCO)
// ==========================================
log(pastaObra, '');
log(pastaObra, '📂 MODO: RE-EXECUÇÃO (lendo do disco)');
log(pastaObra, '═══════════════════════════════════════════════════════════');

const imagensNoDisco = listarImagensNoDisco(pastaObra);
log(pastaObra, `   📷 Total de imagens no disco: ${imagensNoDisco.length}`);

if (imagensNoDisco.length === 0) {
  log(pastaObra, `❌ Nenhuma imagem encontrada no disco!`, 'ERROR');
  return [{
    json: {
      _erro: true,
      _erroTipo: 'SEM_IMAGENS',
      _erroMensagem: 'Nenhuma imagem numerada encontrada na pasta',
      obra, capitulo, pastaObra
    }
  }];
}

const primeiraImagem = imagensNoDisco[0].numero;
const ultimaImagem = imagensNoDisco[imagensNoDisco.length - 1].numero;

log(pastaObra, `   📄 Primeira imagem: ${primeiraImagem}`);
log(pastaObra, `   📄 Última imagem: ${ultimaImagem}`);

const estado = carregarEstado(pastaObra);
const { pendentes, jaProcessadas } = identificarPaginasPendentes(imagensNoDisco, estado);

log(pastaObra, '');
log(pastaObra, '📋 COMPARAÇÃO DISCO vs ESTADO:');
log(pastaObra, `   ✅ Já processadas (status=ok): ${jaProcessadas.length}`);
log(pastaObra, `   ⏳ PENDENTES: ${pendentes.length}`);

let imagensParaProcessar = [...pendentes];

if (CONFIG.PAGINA_INICIAL_MANUAL > 0) {
  imagensParaProcessar = imagensParaProcessar.filter(img => img.numero >= CONFIG.PAGINA_INICIAL_MANUAL);
  log(pastaObra, `🔴 Filtro manual: página >= ${CONFIG.PAGINA_INICIAL_MANUAL}`);
}

if (CONFIG.PAGINA_FINAL_MANUAL > 0) {
  imagensParaProcessar = imagensParaProcessar.filter(img => img.numero <= CONFIG.PAGINA_FINAL_MANUAL);
  log(pastaObra, `🔴 Filtro manual: página <= ${CONFIG.PAGINA_FINAL_MANUAL}`);
}

log(pastaObra, `📥 Total para processar: ${imagensParaProcessar.length}`);

if (imagensParaProcessar.length === 0) {
  log(pastaObra, '');
  log(pastaObra, '✅ TODAS AS PÁGINAS JÁ FORAM PROCESSADAS!');
  return [{ 
    json: { 
      status: 'TUDO_PROCESSADO', 
      obra, 
      capitulo, 
      pastaObra, 
      totalNoDisco: imagensNoDisco.length, 
      totalProcessadas: jaProcessadas.length, 
      mensagem: 'Todas as páginas já foram processadas com sucesso anteriormente'
    } 
  }];
}

log(pastaObra, '');
log(pastaObra, '🔄 PROCESSANDO IMAGENS PENDENTES...');

const efeitosRecomendados = estado?.efeitosRecomendados || {};
const processados = [];
const erros = [];

for (let i = 0; i < imagensParaProcessar.length; i++) {
  const img = imagensParaProcessar[i];
  const paginaGlobal = img.numero;
  const caminhoOriginal = img.caminho;
  const caminhoEditado = caminhoOriginal.replace('.jpg', '_editado.jpg');

  log(pastaObra, `   📄 Página ${paginaGlobal} (${i + 1}/${imagensParaProcessar.length})...`);

  const efeito = selecionarEfeito(img.arquivo, paginaGlobal, efeitosRecomendados);
  const resultadoEfeito = aplicarEfeito(caminhoOriginal, caminhoEditado, efeito, pastaObra);

  if (resultadoEfeito.sucesso) {
    log(pastaObra, `      ✨ Efeito: ${efeito.filterName}`);
  } else if (resultadoEfeito.usouFallback) {
    log(pastaObra, `      ⚠️ Fallback (copiou original)`);
  } else {
    log(pastaObra, `      ❌ Erro: ${resultadoEfeito.erro}`, 'ERROR');
    erros.push(paginaGlobal);
    continue;
  }

  const bufferAgente = comprimirParaAgente(caminhoEditado, pastaObra); // Usa editado

  processados.push({
    paginaGlobal,
    paginaLocal: paginaGlobal,
    nomeOriginal: img.arquivo,
    caminhoOriginal,
    caminhoEditado,
    efeito: efeito.filterName,
    efeitoCategoria: efeito.filterCategoria,
    bufferAgente
  });
}

if (processados.length === 0) {
  log(pastaObra, '❌ Nenhuma página foi processada com sucesso!', 'ERROR');
  return [{
    json: {
      _erro: true,
      _erroTipo: 'ERRO_PROCESSAMENTO',
      _erroMensagem: 'Nenhuma página foi processada com sucesso',
      obra, capitulo, pastaObra,
      paginasErro: erros
    }
  }];
}

processados.sort((a, b) => a.paginaGlobal - b.paginaGlobal);

const binarios = {};
const listaPaginas = [];
const metadados = [];

for (let i = 0; i < processados.length; i++) {
  const p = processados[i];
  const novaChave = i === 0 ? 'data' : `data${i}`;

  binarios[novaChave] = {
    data: p.bufferAgente.toString('base64'),
    mimeType: 'image/jpeg',
    fileName: `${p.paginaGlobal}.jpg`
  };

  listaPaginas.push(p.paginaGlobal);

  metadados.push({
    pagina_numero: p.paginaGlobal,
    paginaGlobal: p.paginaGlobal,
    paginaLocal: p.paginaLocal,
    nome_original: p.nomeOriginal,
    caminho_original: p.caminhoOriginal,
    caminho_editado: p.caminhoEditado,
    effectUsedName: p.efeito,
    effectCategoria: p.efeitoCategoria
  });
}

log(pastaObra, '');
log(pastaObra, '═══════════════════════════════════════════════════════════');
log(pastaObra, '📊 RESUMO FINAL (MODO DISCO)');
log(pastaObra, '═══════════════════════════════════════════════════════════');
log(pastaObra, `📁 Obra: ${obra}`);
log(pastaObra, `📖 Capítulo: ${capitulo}`);
log(pastaObra, `📷 Total no disco: ${imagensNoDisco.length}`);
log(pastaObra, `✅ Já processadas: ${jaProcessadas.length}`);
log(pastaObra, `📥 Processadas agora: ${processados.length}`);
log(pastaObra, `📄 Páginas: ${listaPaginas[0]} - ${listaPaginas[listaPaginas.length - 1]}`);
log(pastaObra, '═══════════════════════════════════════════════════════════');

return [{
  json: {
    info: `Lote com ${listaPaginas.length} imagens`,
    paginas_neste_lote: listaPaginas.join(", "),
    primeira_pagina: listaPaginas[0],
    ultima_pagina: listaPaginas[listaPaginas.length - 1],
    contexto_lote: `ATENÇÃO: Este lote contém as páginas: ${listaPaginas.join(", ")}. Continue a história de onde parou.`,
    obra: obra,
    capitulo: capitulo,
    pastaObra: pastaObra,
    metadados_paginas: metadados,
    total_paginas: listaPaginas.length,

    _efeitosUsados: metadados.map(m => ({
      pagina: m.paginaGlobal,
      efeito: m.effectUsedName,
      categoria: m.effectCategoria
    })),

    _infoParaSalvar: primeiroItem._controle?._infoParaSalvar || primeiroItem._infoParaSalvar || {}
  },
  binary: binarios
}];

