function criarPastaSeNaoExiste(caminho) {
  if (!fs.existsSync(caminho)) {
    try {
      fs.mkdirSync(caminho, { recursive: true });
      console.log(`📁 Pasta criada: ${caminho}`);
      return true;
    } catch (e) {
      console.error(`❌ Erro ao criar pasta ${caminho}: ${e.message}`);
      return false;
    }
  }
  return true;
}

function log(pastaObra, mensagem, tipo = 'INFO') {
  const timestamp = new Date().toISOString();
  const linha = `[${timestamp}] [${tipo}] ${mensagem}`;

  console.log(linha);

  if (CONFIG.salvarLogs && pastaObra) {
    try {
      const pastaLogs = path.join(pastaObra, CONFIG.pastaLogs);
      criarPastaSeNaoExiste(pastaLogs);

      const dataHoje = new Date().toISOString().split('T')[0];
      const arquivoLog = path.join(pastaLogs, `processa_agente_${dataHoje}.log`);
      fs.appendFileSync(arquivoLog, linha + '\n', 'utf8');
    } catch (e) {}
  }
}

function debug(pastaObra, mensagem) {
  if (CONFIG.DEBUG) {
    log(pastaObra, `[DEBUG] ${mensagem}`, 'DEBUG');
  }
}

// ==========================================
// 🆕 FUNÇÕES DE BACKUP APRIMORADAS
// ==========================================

/**
 * Gera nome do arquivo de backup com timestamp
 */
function gerarNomeBackup() {
  const agora = new Date();
  const timestamp = agora.toISOString()
    .replace(/[:\-]/g, '')
    .replace('T', '_')
    .replace(/\.\d{3}Z$/, '');
  return `estado_backup_${timestamp}.json`;
}

/**
 * Lista todos os backups existentes ordenados por data (mais recente primeiro)
 */
function listarBackups(pastaBackups) {
  if (!fs.existsSync(pastaBackups)) {
    return [];
  }

  try {
    const arquivos = fs.readdirSync(pastaBackups)
      .filter(f => f.startsWith('estado_backup_') && f.endsWith('.json'))
      .map(f => {
        const caminhoCompleto = path.join(pastaBackups, f);
        const stats = fs.statSync(caminhoCompleto);
        return {
          nome: f,
          caminho: caminhoCompleto,
          criadoEm: stats.mtime,
          tamanho: stats.size
        };
      })
      .sort((a, b) => b.criadoEm - a.criadoEm); // Mais recente primeiro

    return arquivos;
  } catch (e) {
    console.error(`❌ Erro ao listar backups: ${e.message}`);
    return [];
  }
}

/**
 * Remove backups antigos mantendo apenas os mais recentes
 */
function limparBackupsAntigos(pastaBackups, maxBackups) {
  if (maxBackups <= 0) return; // 0 = ilimitado

  const backups = listarBackups(pastaBackups);

  if (backups.length <= maxBackups) {
    return;
  }

  // Remove os mais antigos
  const backupsParaRemover = backups.slice(maxBackups);

  for (const backup of backupsParaRemover) {
    try {
      fs.unlinkSync(backup.caminho);
      console.log(`🗑️ Backup antigo removido: ${backup.nome}`);
    } catch (e) {
      console.error(`❌ Erro ao remover backup ${backup.nome}: ${e.message}`);
    }
  }
}

/**
 * Cria backup do arquivo de estado atual
 */
function criarBackup(pastaObra) {
  const caminhoEstado = path.join(pastaObra, CONFIG.arquivoEstado);

  if (!fs.existsSync(caminhoEstado)) {
    console.log('ℹ️ Arquivo de estado não existe, backup não necessário');
    return { sucesso: false, motivo: 'arquivo_nao_existe' };
  }

  const pastaBackups = path.join(pastaObra, CONFIG.pastaBackups);
  criarPastaSeNaoExiste(pastaBackups);

  const nomeBackup = gerarNomeBackup();
  const caminhoBackup = path.join(pastaBackups, nomeBackup);

  try {
    // Lê o estado atual
    const conteudoAtual = fs.readFileSync(caminhoEstado, 'utf8');
    const estadoAtual = JSON.parse(conteudoAtual);

    // Adiciona metadados do backup
    const backupData = {
      _metaBackup: {
        criadoEm: new Date().toISOString(),
        arquivoOriginal: CONFIG.arquivoEstado,
        versao: 'v10'
      },
      ...estadoAtual
    };

    // Salva o backup
    fs.writeFileSync(caminhoBackup, JSON.stringify(backupData, null, 2), 'utf8');

    console.log(`💾 Backup criado: ${nomeBackup}`);

    // Limpa backups antigos
    limparBackupsAntigos(pastaBackups, CONFIG.maxBackups);

    return {
      sucesso: true,
      arquivo: nomeBackup,
      caminho: caminhoBackup,
      tamanho: fs.statSync(caminhoBackup).size
    };
  } catch (e) {
    console.error(`❌ Erro ao criar backup: ${e.message}`);
    return { sucesso: false, motivo: e.message };
  }
}

// ==========================================
// FUNÇÕES DE ESTADO
// ==========================================

// 🔴 FUNÇÃO ORIGINAL MANTIDA - backup simples para .bak
function backupEstado(caminhoEstado) {
  if (fs.existsSync(caminhoEstado)) {
    try {
      const caminhoBackup = caminhoEstado + '.bak';
      fs.copyFileSync(caminhoEstado, caminhoBackup);
      return true;
    } catch (e) {
      return false;
    }
  }
  return false;
}

function carregarEstado(pastaObra) {
  const caminhoEstado = path.join(pastaObra, CONFIG.arquivoEstado);

  debug(pastaObra, `Tentando carregar estado de: ${caminhoEstado}`);

  if (fs.existsSync(caminhoEstado)) {
    try {
      const conteudo = fs.readFileSync(caminhoEstado, 'utf8');
      const estado = JSON.parse(conteudo);
      debug(pastaObra, `Estado carregado. Última página global: ${estado.ultimaPaginaGlobal || 0}`);
      return estado;
    } catch (e) {
      log(pastaObra, `Erro ao carregar estado: ${e.message}`, 'WARN');
      return criarEstadoVazio();
    }
  }

  debug(pastaObra, 'Arquivo de estado não existe, criando novo');
  return criarEstadoVazio();
}

function criarEstadoVazio() {
  return {
    obra: '',
    ultimaAtualizacao: new Date().toISOString(),
    ultimaPaginaGlobal: 0,
    capitulos: {},
    paginasProcessadas: {},
    efeitosRecomendados: {},
    historicoNarracoes: {},
    personagens: {},
    estatisticas: {
      totalNarracoesGeradas: 0,
      totalPaginasProcessadas: 0,
      ultimoProcessamento: null
    }
  };
}

function salvarEstado(pastaObra, estado) {
  if (CONFIG.MODO_TESTE) {
    console.log('');
    console.log('⚠️ MODO_TESTE ativo - Estado NÃO foi salvo!');
    return false;
  }

  criarPastaSeNaoExiste(pastaObra);

  const caminhoEstado = path.join(pastaObra, CONFIG.arquivoEstado);
  estado.ultimaAtualizacao = new Date().toISOString();

  // 🔴 BACKUP ORIGINAL MANTIDO - cria .bak
  backupEstado(caminhoEstado);

  // 🆕 NOVO: Cria backup com timestamp na pasta separada
  if (CONFIG.criarBackupAntesDeSalvar) {
    criarBackup(pastaObra);
  }

  try {
    fs.writeFileSync(caminhoEstado, JSON.stringify(estado, null, 2), 'utf8');
    log(pastaObra, `💾 Estado salvo: ${caminhoEstado}`);
    return true;
  } catch (e) {
    log(pastaObra, `❌ Erro ao salvar estado: ${e.message}`, 'ERROR');
    return false;
  }
}

function descobrirUltimaPaginaProcessada(estado) {
  const paginasOk = Object.entries(estado.paginasProcessadas || {})
    .filter(([k, v]) => v.status === 'ok')
    .map(([k, v]) => parseInt(k));

  if (paginasOk.length === 0) {
    return 0;
  }

  return Math.max(...paginasOk);
}

