// ==========================================
// FUNÇÕES DE ANÁLISE
// ==========================================
function analisarEmocaoPagina(falas) {
  const textoCompleto = falas
    .map(n => (n.texto || '').toLowerCase())
    .join(' ');

  const scores = {};

  for (const [emocao, config] of Object.entries(MAPA_EMOCOES_EFEITOS)) {
    scores[emocao] = 0;
    for (const palavra of config.palavras) {
      const regex = new RegExp(palavra.toLowerCase(), 'gi');
      const matches = textoCompleto.match(regex);
      if (matches) {
        scores[emocao] += matches.length;
      }
    }
  }

  let emocaoDominante = 'neutro';
  let maiorScore = 0;

  for (const [emocao, score] of Object.entries(scores)) {
    if (score > maiorScore) {
      maiorScore = score;
      emocaoDominante = emocao;
    }
  }

  const configEmocao = MAPA_EMOCOES_EFEITOS[emocaoDominante];

  return {
    emocao: emocaoDominante,
    efeitoRecomendado: configEmocao.efeitoRecomendado,
    efeitoIndice: configEmocao.efeitoIndice
  };
}

function extrairPersonagens(todasFalas) {
  const personagens = {};

  for (const fala of todasFalas) {
    const nome = fala.nome || 'DESCONHECIDO';

    if (!personagens[nome]) {
      personagens[nome] = {
        genero: fala.genero || 'UNKNOWN',
        aparicoes: 0
      };
    }

    personagens[nome].aparicoes++;
    personagens[nome].genero = fala.genero || personagens[nome].genero;
  }

  return personagens;
}

