// Limpeza básica do Markdown
const textoLimpo = textoBruto.replace(/```json/g, '').replace(/```/g, '').trim();

// Tenta fazer o parse direto (o Gemini costuma mandar um array único agora)
let todosOsItens = [];
try {
    // Se houver separadores |==|, trata cada bloco
    if (textoLimpo.includes('|==|')) {
        const blocos = textoLimpo.split('|==|');
        for (const bloco of blocos) {
            const parsed = JSON.parse(bloco.trim());
            todosOsItens = todosOsItens.concat(Array.isArray(parsed) ? parsed : [parsed]);
        }
    } else {
        // Se for um JSON único (o mais comum no seu prompt atual)
        const parsed = JSON.parse(textoLimpo);
        todosOsItens = Array.isArray(parsed) ? parsed : [parsed];
    }
} catch (e) {
    return [{ json: { erro: "Falha no Parse JSON", raw: textoBruto, detalhe: e.message } }];
}

