/**
 * Lista todos os backups existentes ordenados por data (mais recente primeiro)
 */
function listarBackups(pastaBackups) {
  if (!fs.existsSync(pastaBackups)) {
    return [];
  }

  try {
    const arquivos = fs.readdirSync(pastaBackups)
      .filter(f => f.startsWith('estado_backup_') && f.endsWith('.json'))
      .map(f => {
        const caminhoCompleto = path.join(pastaBackups, f);
        const stats = fs.statSync(caminhoCompleto);

        // Extrai timestamp do nome do arquivo
        const match = f.match(/estado_backup_(\d{8})_(\d{6})\.json/);
        let dataFormatada = 'Desconhecida';
        if (match) {
          const data = match[1];
          const hora = match[2];
          dataFormatada = `${data.slice(6,8)}/${data.slice(4,6)}/${data.slice(0,4)} ${hora.slice(0,2)}:${hora.slice(2,4)}:${hora.slice(4,6)}`;
        }

        return {
          nome: f,
          caminho: caminhoCompleto,
          criadoEm: stats.mtime,
          dataFormatada: dataFormatada,
          tamanho: stats.size,
          tamanhoFormatado: formatarTamanho(stats.size)
        };
      })
      .sort((a, b) => b.criadoEm - a.criadoEm); // Mais recente primeiro

    return arquivos;
  } catch (e) {
    console.error(`❌ Erro ao listar backups: ${e.message}`);
    return [];
  }
}

function formatarTamanho(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

/**
 * Gera nome do arquivo de backup com timestamp
 */
function gerarNomeBackup(prefixo = 'estado_backup') {
  const agora = new Date();
  const timestamp = agora.toISOString()
    .replace(/[:\-]/g, '')
    .replace('T', '_')
    .replace(/\.\d{3}Z$/, '');
  return `${prefixo}_${timestamp}.json`;
}

/**
 * Cria backup do estado atual
 */
function criarBackupAtual(pastaObra) {
  const caminhoEstado = path.join(pastaObra, CONFIG.arquivoEstado);

  if (!fs.existsSync(caminhoEstado)) {
    return { sucesso: false, motivo: 'estado_nao_existe' };
  }

  const pastaBackups = path.join(pastaObra, CONFIG.pastaBackups);
  criarPastaSeNaoExiste(pastaBackups);

  // Usa prefixo diferente para backups de pré-restauração
  const nomeBackup = gerarNomeBackup('estado_pre_restore');
  const caminhoBackup = path.join(pastaBackups, nomeBackup);

  try {
    const conteudoAtual = fs.readFileSync(caminhoEstado, 'utf8');
    const estadoAtual = JSON.parse(conteudoAtual);

    const backupData = {
      _metaBackup: {
        criadoEm: new Date().toISOString(),
        tipo: 'pre_restauracao',
        arquivoOriginal: CONFIG.arquivoEstado
      },
      ...estadoAtual
    };

    fs.writeFileSync(caminhoBackup, JSON.stringify(backupData, null, 2), 'utf8');

    return {
      sucesso: true,
      arquivo: nomeBackup,
      caminho: caminhoBackup
    };
  } catch (e) {
    return { sucesso: false, motivo: e.message };
  }
}

/**
 * Restaura um backup específico
 */
function restaurarBackup(pastaObra, backupParaRestaurar) {
  const caminhoEstado = path.join(pastaObra, CONFIG.arquivoEstado);

  try {
    // Lê o backup
    const conteudoBackup = fs.readFileSync(backupParaRestaurar.caminho, 'utf8');
    const dadosBackup = JSON.parse(conteudoBackup);

    // Remove metadados do backup antes de restaurar
    delete dadosBackup._metaBackup;

    // Adiciona info de restauração
    dadosBackup._restauracao = {
      restauradoEm: new Date().toISOString(),
      backupOrigem: backupParaRestaurar.nome,
      backupData: backupParaRestaurar.dataFormatada
    };

    // Salva como estado atual
    fs.writeFileSync(caminhoEstado, JSON.stringify(dadosBackup, null, 2), 'utf8');

    return { sucesso: true };
  } catch (e) {
    return { sucesso: false, motivo: e.message };
  }
}

/**
 * Carrega e analisa um backup para preview
 */
function analisarBackup(caminhoBackup) {
  try {
    const conteudo = fs.readFileSync(caminhoBackup, 'utf8');
    const dados = JSON.parse(conteudo);

    return {
      obra: dados.obra || 'N/A',
      ultimaPaginaGlobal: dados.ultimaPaginaGlobal || 0,
      totalCapitulos: Object.keys(dados.capitulos || {}).length,
      totalPaginasProcessadas: Object.keys(dados.paginasProcessadas || {}).length,
      totalPersonagens: Object.keys(dados.personagens || {}).length,
      ultimaAtualizacao: dados.ultimaAtualizacao || 'N/A',
      metaBackup: dados._metaBackup || null
    };
  } catch (e) {
    return null;
  }
}

