// ==========================================
// FUNÇÕES DE LOG
// ==========================================
function criarPastaLogs(pastaObra) {
  const pastaLogs = path.join(pastaObra, CONFIG.pastaLogs);
  if (!fs.existsSync(pastaLogs)) {
    fs.mkdirSync(pastaLogs, { recursive: true });
  }
  return pastaLogs;
}

function log(pastaObra, mensagem, tipo = 'INFO') {
  const timestamp = new Date().toISOString();
  const linha = `[${timestamp}] [${tipo}] ${mensagem}`;

  console.log(linha);

  if (CONFIG.salvarLogs && pastaObra) {
    try {
      const pastaLogs = criarPastaLogs(pastaObra);
      const dataHoje = new Date().toISOString().split('T')[0];
      const arquivoLog = path.join(pastaLogs, `gerenciador_${dataHoje}.log`);
      fs.appendFileSync(arquivoLog, linha + '\n', 'utf8');
    } catch (e) {}
  }
}

// ==========================================
// FUNÇÕES AUXILIARES
// ==========================================
function extrairNumeroCapitulo(nomeCapitulo) {
  const match = nomeCapitulo.match(/cap[itulo]*\s*(\d+)/i);
  return match ? parseInt(match[1], 10) : 1;
}

function backupEstado(caminhoEstado) {
  if (fs.existsSync(caminhoEstado)) {
    try {
      fs.copyFileSync(caminhoEstado, caminhoEstado + '.bak');
      return true;
    } catch (e) {
      return false;
    }
  }
  return false;
}

function carregarEstado(pastaObra) {
  if (CONFIG.IGNORAR_ESTADO) {
    console.log('⚠️ IGNORAR_ESTADO=true - Não carregando estado');
    return criarEstadoVazio();
  }

  const caminhoEstado = path.join(pastaObra, CONFIG.arquivoEstado);

  if (fs.existsSync(caminhoEstado)) {
    try {
      const conteudo = fs.readFileSync(caminhoEstado, 'utf8');
      const estado = JSON.parse(conteudo);

      // Conta páginas com status 'ok'
      const paginasOk = Object.entries(estado.paginasProcessadas || {})
        .filter(([k, v]) => v.status === 'ok')
        .map(([k, v]) => parseInt(k));

      log(pastaObra, `📂 Estado carregado: ${paginasOk.length} páginas com status='ok'`);

      if (paginasOk.length > 0) {
        log(pastaObra, `   Páginas OK: ${paginasOk.slice(0, 10).join(', ')}${paginasOk.length > 10 ? '...' : ''}`);
        log(pastaObra, `   Última página OK: ${Math.max(...paginasOk)}`);
      }

      return estado;
    } catch (e) {
      log(pastaObra, `Erro ao carregar estado: ${e.message}`, 'WARN');
    }
  } else {
    log(pastaObra, `📂 Arquivo de estado não existe: ${caminhoEstado}`);
  }

  return criarEstadoVazio();
}

function criarEstadoVazio() {
  return {
    obra: '',
    ultimaAtualizacao: new Date().toISOString(),
    ultimaPaginaGlobal: 0,
    capitulos: {},
    paginasProcessadas: {},
    efeitosRecomendados: {},
    personagens: {},
    estatisticas: {}
  };
}

function salvarEstado(pastaObra, estado) {
  if (!CONFIG.SALVAR_ESTADO_AQUI) {
    log(pastaObra, '⏭️ Salvamento desativado neste node');
    return false;
  }

  const caminhoEstado = path.join(pastaObra, CONFIG.arquivoEstado);
  estado.ultimaAtualizacao = new Date().toISOString();

  if (!fs.existsSync(pastaObra)) {
    fs.mkdirSync(pastaObra, { recursive: true });
  }

  backupEstado(caminhoEstado);
  fs.writeFileSync(caminhoEstado, JSON.stringify(estado, null, 2), 'utf8');
  log(pastaObra, `💾 Estado salvo: ${caminhoEstado}`);
  return true;
}

function verificarImagensNoDisco(pastaObra, paginaInicial, paginaFinal) {
  if (CONFIG.IGNORAR_DISCO) {
    console.log('⚠️ IGNORAR_DISCO=true - Não verificando disco');
    return {
      todasExistem: false,
      corrompidas: [],
      faltando: Array.from({length: paginaFinal - paginaInicial + 1}, (_, i) => paginaInicial + i),
      validas: []
    };
  }

  const resultado = {
    todasExistem: true,
    corrompidas: [],
    faltando: [],
    validas: []
  };

  for (let p = paginaInicial; p <= paginaFinal; p++) {
    const caminhoImg = path.join(pastaObra, `${p}.jpg`);

    if (!fs.existsSync(caminhoImg)) {
      resultado.todasExistem = false;
      resultado.faltando.push(p);
    } else {
      try {
        const stats = fs.statSync(caminhoImg);
        if (stats.size < CONFIG.tamanhoMinimoBytes) {
          resultado.todasExistem = false;
          resultado.corrompidas.push(p);
        } else {
          resultado.validas.push(p);
        }
      } catch (e) {
        resultado.todasExistem = false;
        resultado.faltando.push(p);
      }
    }
  }

  return resultado;
}

// 🔴 FUNÇÃO CORRIGIDA - Conta páginas pelo ESTADO, não pelo disco
function contarPaginasJaProcessadas(estado, paginaInicial, paginaFinal) {
  if (CONFIG.IGNORAR_ESTADO || CONFIG.FORCAR_REPROCESSAMENTO) {
    // Se ignorando estado ou forçando, tudo é pendente
    return {
      paginasOk: [],
      paginasPendentes: Array.from({length: paginaFinal - paginaInicial + 1}, (_, i) => paginaInicial + i)
    };
  }

  const paginasOk = [];
  const paginasPendentes = [];

  for (let p = paginaInicial; p <= paginaFinal; p++) {
    const infoPagina = estado.paginasProcessadas?.[p];

    // 🔴 IMPORTANTE: Só considera 'ok' se tiver status='ok'
    if (infoPagina && infoPagina.status === 'ok') {
      paginasOk.push(p);
    } else {
      paginasPendentes.push(p);
    }
  }

  return { paginasOk, paginasPendentes };
}

