 * Garante que o código não pare se o nó anterior mudar de nome.
 */
function findBinary(item) {
    if (!item || !item.binary) return null;
    const keys = Object.keys(item.binary);
    if (keys.length > 0) {
        binaryPropName = keys[0];
        return item.binary[keys[0]];
    }
    return null;
}

