let imgH = 1500;
if (binaryPack && binaryPack.metadata) {
    const w = parseInt(binaryPack.metadata.width);
    const h = parseInt(binaryPack.metadata.height);
    if (!isNaN(w) && w > 0) { imgW = w; imgH = h; }
}

// 2. FUNÇÕES AUXILIARES DE CÁLCULO ESPACIAL
function getCoords(x, y, w, h) {
    let safeX = Math.max(0, Math.floor(x));
    let safeY = Math.max(0, Math.floor(y));
    let safeW = Math.floor(w);
    let safeH = Math.floor(h);

    // Trava de segurança para não exceder os limites da imagem
    if (safeX + safeW > imgW) safeW = imgW - safeX;
    if (safeY + safeH > imgH) safeH = imgH - safeY;

    return { x: safeX, y: safeY, w: safeW, h: safeH };
}

/**
 * Expande a caixa de censura em 30% (Aumentado na V21)
 * Crucial para cobrir o "contorno" da pele que a IA do YouTube detecta.
 */
function expandBox(box, percentual = 0.30) {
    const margemW = box.w * percentual;
    const margemH = box.h * percentual;
    return getCoords(
        box.x - margemW,
        box.y - margemH,
        box.w + (margemW * 2),
        box.h + (margemH * 2)
    );
}

/**
 * Merge de caixas próximas (Vizinhança de 70px)
 * Evita deixar "frestas" de pele entre duas censuras.
 */
function mergeNearbyBoxes(boxes, distancia = 70) {
    if (boxes.length < 2) return boxes;
    let merged = true;
    while(merged) {
        merged = false;
        for (let i = 0; i < boxes.length; i++) {
            for (let j = i + 1; j < boxes.length; j++) {
                const b1 = boxes[i];
                const b2 = boxes[j];
                const cx1 = b1.x + b1.w/2; const cy1 = b1.y + b1.h/2;
                const cx2 = b2.x + b2.w/2; const cy2 = b2.y + b2.h/2;
                const dist = Math.sqrt(Math.pow(cx1-cx2, 2) + Math.pow(cy1-cy2, 2));

                if (dist < distancia + Math.max(b1.w, b2.w)/2) {
                    const xMin = Math.min(b1.x, b2.x);
                    const yMin = Math.min(b1.y, b2.y);
                    const xMax = Math.max(b1.x + b1.w, b2.x + b2.w);
                    const yMax = Math.max(b1.y + b1.h, b2.y + b2.h);
                    boxes[i] = getCoords(xMin, yMin, xMax - xMin, yMax - yMin);
                    boxes.splice(j, 1);
                    merged = true;
                    break;
                }
            }
            if(merged) break;
        }
    }
    return boxes;
}

