// REGRAS DE PADRONIZAÇÃO DE TAGS (NOVAS V6)
const REGRAS_TAGS = [
    { reg: /\[.*risada.*\]|\[.*rindo.*\]|\[.*risos.*\]/gi, sub: "[RISO]" },
    { reg: /\[.*grito.*\]|\[.*berro.*\]/gi, sub: "[GRITANDO]" },
    { reg: /\[.*choro.*\]|\[.*chorando.*\]/gi, sub: "[CHORANDO]" },
    { reg: /\[.*sussurro.*\]|\[.*baixo.*\]/gi, sub: "[SUSSURRO]" },
    { reg: /\[.*medo.*\]|\[.*assustado.*\]/gi, sub: "[MEDO]" },
    { reg: /\[.*feliz.*\]|\[.*alegre.*\]/gi, sub: "[FELIZ]" },
    { reg: /\[.*raiva.*\]|\[.*furioso.*\]/gi, sub: "[RAIVA]" },
    { reg: /\[.*confuso.*\]|\[.*duvida.*\]/gi, sub: "[CONFUSO]" },
    { reg: /\[.*serio.*\]/gi, sub: "[SERIO]" },
    { reg: /\[.*ironia.*\]/gi, sub: "[IRONICO]" },
    { reg: /\[.*deboche.*\]/gi, sub: "[DEBOCHE]" },
    { reg: /\[.*surpresa.*\]/gi, sub: "[SURPRESO]" }
];

// Função auxiliar de limpeza e substituição
function sanearTexto(texto) {
    if (!texto || typeof texto !== 'string') return texto;
    let textoLimpo = texto;

    // 1. Aplica substituição de palavras e gírias (Segurança + Viral)
    for (const regra of REGRAS) {
        textoLimpo = textoLimpo.replace(regra.reg, regra.sub);
    }

    // 2. Padroniza Tags de Emoção (Para o próximo node entender melhor)
    // Isso garante que [risada nervosa] vire [RISO] para a IA de áudio processar.
    for (const regra of REGRAS_TAGS) {
        textoLimpo = textoLimpo.replace(regra.reg, regra.sub);
    }

    return textoLimpo;
}

// =========================================================
// LÓGICA DE PRESERVAÇÃO DE ESTRUTURA (MAP)
// =========================================================
return items.map(item => {
    const json = item.json;

    // 1. Verifica se existe o array de falas (Formato padrão)
    if (json.falas && Array.isArray(json.falas)) {
        json.falas = json.falas.map(fala => {
            if (!fala.texto) return fala;

            const original = fala.texto;
            const processado = sanearTexto(fala.texto);

            // Só altera se houve mudança real
            if (original !== processado) {
                fala.texto = processado;       // APLICA
                fala._texto_viralizado = true; // Debug
            }
            return fala;
        });
    }

    // 2. Verifica se é um item de RESUMO (Backup/Formato antigo)
    if (json._tipo === 'RESUMO' && json.content && json.content.parts) {
         json.content.parts.forEach(part => {
             if (part.text) part.text = sanearTexto(part.text);
         });
    }

    return item;
});

// ======================================================================
// NODE: CORRIGE JSON V11 - RESPEITA PAGINAÇÃO ORIGINAL
// ======================================================================

const inputItem = $('narrador').first(); 
const geminiResponse = inputItem?.json ?? inputItem;
const textoBruto = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

if (!textoBruto) {
    return [{ json: { erro: "Texto vazio do Gemini", raw_input: inputItem } }];
}

// Limpeza básica do Markdown
const textoLimpo = textoBruto.replace(/```json/g, '').replace(/```/g, '').trim();

// Tenta fazer o parse direto (o Gemini costuma mandar um array único agora)
let todosOsItens = [];
try {
    // Se houver separadores |==|, trata cada bloco
    if (textoLimpo.includes('|==|')) {
        const blocos = textoLimpo.split('|==|');
        for (const bloco of blocos) {
            const parsed = JSON.parse(bloco.trim());
            todosOsItens = todosOsItens.concat(Array.isArray(parsed) ? parsed : [parsed]);
        }
    } else {
        // Se for um JSON único (o mais comum no seu prompt atual)
        const parsed = JSON.parse(textoLimpo);
        todosOsItens = Array.isArray(parsed) ? parsed : [parsed];
    }
} catch (e) {
    return [{ json: { erro: "Falha no Parse JSON", raw: textoBruto, detalhe: e.message } }];
}

// 2. AGRUPAMENTO INTELIGENTE POR PÁGINA REAL
// Aqui está o segredo: Agrupar pelo número da 'pagina' que veio do Gemini
const paginasMap = new Map();

todosOsItens.forEach(item => {
    // Pega o número real que o Gemini mandou (ex: 25)
    // Se não tiver, usa 0 ou trata erro
    const numPagina = item.pagina;

    if (!paginasMap.has(numPagina)) {
        paginasMap.set(numPagina, {
            pagina_numero: numPagina,
            falas: []
        });
    }

    // Adiciona a fala dentro da página correta
    paginasMap.get(numPagina).falas.push({
        pagina: item.pagina,
        ordem: item.ordem,
        nome: item.nome || "NARRADOR",
        genero: item.genero || "MALE", // Mantém compatibilidade se precisar
        texto: typeof item.texto === 'string' ? item.texto : JSON.stringify(item.texto)
    });
});

// 3. RETORNA O ARRAY FINAL ORGANIZADO
// Transforma o Map em Array e ordena pelo número da página para garantir a sequência
const resultadoFinal = Array.from(paginasMap.values()).sort((a, b) => a.pagina_numero - b.pagina_numero);

// Retorna cada página como um item separado para o n8n processar (se for esse o objetivo)
// Ou retorna tudo junto se preferir. Abaixo retorna 1 item por página (padrão n8n)
return resultadoFinal.map(p => ({ json: p }));

